      name: 'catalog_search',
      description: 'Search the catalog by name (case-insensitive) with pagination.',
      inputSchema: {
        type: 'object',
        properties: {
          query: { type: 'string' },
          offset: { type: 'integer', default: 0 },
          limit: { type: 'integer', default: 2, minimum: 1, maximum: 5 }
        },
        required: ['query'],
        additionalProperties: false
      }
    }
  ];
}

export async function callTool(name, args) {
  if (name !== 'catalog_search') {
    throw new Error('Unknown tool: ' + name);
  }

  const { query, offset = 0, limit = 2, ...extra } = args || {};

  // Validate query
  if (typeof query !== 'string') {
    throw new Error('query must be a string');
  }

  // Check for extra properties
  if (Object.keys(extra).length > 0) {
    throw new Error('Unexpected arguments: ' + Object.keys(extra).join(', '));
  }

  // Validate offset
  if (!Number.isInteger(offset) || offset < 0) {
    throw new Error('offset must be a non-negative integer');
  }

  // Validate limit
  if (!Number.isInteger(limit) || limit < 1 || limit > 5) {
    throw new Error('limit must be an integer between 1 and 5');
  }

  const q = query.toLowerCase();
  const matches = items.filter(item => item.name.toLowerCase().includes(q));

  const slice = matches.slice(offset, offset + limit);
  const hasMore = offset + limit < matches.length;
  const nextOffset = hasMore ? offset + limit : null;

  const result = {
    results: slice,
    count: slice.length,
    total: matches.length,
    next_offset: nextOffset
  };

  return {
    content: [{ type: 'text', text: JSON.stringify(result) }]
  };
}
